            // Same Host main-process entry: enter folders, reveal/select individual files.
            if (metadata.isDirectory()) {
                const error = await shell.openPath(target);
                if (error)
                    fail(error);
            }
            else
                shell.showItemInFolder(target);
        }, async systemTrashTarget(nativeAbsolutePath) {
            if (!isAbsolute(nativeAbsolutePath))
                fail('SOURCE_TARGET_ABSOLUTE_REQUIRED');
            const path = resolve(nativeAbsolutePath);
            if ((await realpath(path)) !== path)
                fail('SYSTEM_TRASH_TARGET_CHANGED');
            await stat(path);
            // Obsidian routes Trash through its main process; renderer COM fails on Windows.
            // Native OS Trash only. Observation must not deadlock the P008 writer.
            await nativeHost().remote.shell.trashItem(path);
        } };
