export async function deleteBoard(command, product, bodyFiles, sourceHost) {
    if (!command.deleteFilesConfirmed)
        throw new Error('请再次确认：整个项目文件夹及其中全部文件将移入系统回收站。');
    const boards = await product.listIkuKanbanBoards();
    const board = boards.find((candidate) => candidate.id === command.id);
    if (!board)
        return { id: command.id, boardId: null };
    if (board.bodyFolder === undefined)
        throw new Error('KANBAN_PROJECT_FOLDER_UNAVAILABLE');
    const target = await bodyFiles.projectTrashTarget(board.bodyFolder, boards
        .filter((candidate) => candidate.id !== board.id)
        .map((candidate) => candidate.bodyFolder ?? ''));
    if (target)
        await sourceHost.systemTrashTarget(target);
    return product.mutateIkuKanban(command);
}
